// VideoChat.jsx
import React, { useEffect, useRef, useState } from 'react';
import './VideoChat.css'; // Стили для видеозвонков

const VideoChat = ({ ws, clientId }) => {
  // Состояния для локального и удалённого видеопотока, состояния звонка и контроля аудио/видео
  const [localStream, setLocalStream] = useState(null);
  const [remoteStream, setRemoteStream] = useState(null);
  const [callStatus, setCallStatus] = useState('idle'); // idle, calling, in_call
  const [audioEnabled, setAudioEnabled] = useState(true);
  const [videoEnabled, setVideoEnabled] = useState(true);

  const localVideoRef = useRef(null);
  const remoteVideoRef = useRef(null);
  const peerConnectionRef = useRef(null);

  // Конфигурация ICE-серверов (STUN/TURN)
  const iceServers = {
    iceServers: [
      { urls: 'stun:stun.l.google.com:19302' },
      // Можно добавить TURN-сервера, если потребуется
    ],
  };

  // Функция начала звонка
  const startCall = async () => {
    try {
      // Получаем локальный поток (аудио и видео)
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      setLocalStream(stream);
      if (localVideoRef.current) localVideoRef.current.srcObject = stream;

      // Создаем RTCPeerConnection
      const pc = new RTCPeerConnection(iceServers);
      peerConnectionRef.current = pc;
      // Добавляем все треки локального потока в соединение
      stream.getTracks().forEach((track) => pc.addTrack(track, stream));

      // Обработка ICE кандидатов – отправляем кандидата через WebSocket
      pc.onicecandidate = (event) => {
        if (event.candidate && ws && ws.readyState === WebSocket.OPEN) {
          ws.send(
            JSON.stringify({
              type: 'video_signal',
              signalType: 'ice_candidate',
              candidate: event.candidate,
              clientId,
            })
          );
        }
      };

      // Обработка входящего видеопотока
      pc.ontrack = (event) => {
        if (remoteVideoRef.current) {
          remoteVideoRef.current.srcObject = event.streams[0];
          setRemoteStream(event.streams[0]);
        }
      };

      // Создаем предложение (offer)
      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);

      // Функция отправки SDP offer с повторными попытками
      const sendOffer = () => {
        if (ws && ws.readyState === WebSocket.OPEN) {
          ws.send(
            JSON.stringify({
              type: 'video_signal',
              signalType: 'video_offer',
              offer,
              clientId,
            })
          );
          console.log('SDP offer отправлен');
        } else {
          console.warn('WebSocket не готов, повторная отправка offer через 2 секунды');
          setTimeout(sendOffer, 2000);
        }
      };

      sendOffer();
      setCallStatus('calling');
    } catch (err) {
      console.error('Ошибка запуска видеозвонка:', err);
    }
  };

  // Функция обработки входящего offer
  const handleOffer = async (data) => {
    try {
      const pc = new RTCPeerConnection(iceServers);
      peerConnectionRef.current = pc;
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      setLocalStream(stream);
      if (localVideoRef.current) localVideoRef.current.srcObject = stream;
      stream.getTracks().forEach((track) => pc.addTrack(track, stream));

      pc.onicecandidate = (event) => {
        if (event.candidate && ws && ws.readyState === WebSocket.OPEN) {
          ws.send(
            JSON.stringify({
              type: 'video_signal',
              signalType: 'ice_candidate',
              candidate: event.candidate,
              clientId,
            })
          );
        }
      };

      pc.ontrack = (event) => {
        if (remoteVideoRef.current) {
          remoteVideoRef.current.srcObject = event.streams[0];
          setRemoteStream(event.streams[0]);
        }
      };

      await pc.setRemoteDescription(new RTCSessionDescription(data.offer));
      const answer = await pc.createAnswer();
      await pc.setLocalDescription(answer);

      if (ws && ws.readyState === WebSocket.OPEN) {
        ws.send(
          JSON.stringify({
            type: 'video_signal',
            signalType: 'video_answer',
            answer,
            clientId,
          })
        );
      }
      setCallStatus('in_call');
    } catch (err) {
      console.error('Ошибка обработки входящего offer:', err);
    }
  };

  // Функция обработки входящего answer
  const handleAnswer = async (data) => {
    try {
      await peerConnectionRef.current.setRemoteDescription(new RTCSessionDescription(data.answer));
      setCallStatus('in_call');
    } catch (err) {
      console.error('Ошибка обработки ответа:', err);
    }
  };

  // Функция обработки ICE кандидатов
  const handleICECandidate = async (data) => {
    try {
      if (data.candidate) {
        await peerConnectionRef.current.addIceCandidate(new RTCIceCandidate(data.candidate));
      }
    } catch (err) {
      console.error('Ошибка добавления ICE кандидата:', err);
    }
  };

  // Обработка сигналов видеозвонка через событие CustomEvent (сигнализация через WebSocket)
  useEffect(() => {
    const signalHandler = (e) => {
      const data = e.detail;
      if (data.signalType === 'video_offer') {
        handleOffer(data);
      } else if (data.signalType === 'video_answer') {
        handleAnswer(data);
      } else if (data.signalType === 'ice_candidate') {
        handleICECandidate(data);
      }
    };
    document.addEventListener('videoSignal', signalHandler);
    return () => {
      document.removeEventListener('videoSignal', signalHandler);
    };
  }, [clientId]);

  // Переключение аудио: включение/выключение микрофона
  const toggleAudio = () => {
    if (localStream) {
      localStream.getAudioTracks().forEach((track) => (track.enabled = !track.enabled));
      setAudioEnabled((prev) => !prev);
    }
  };

  // Переключение видео: включение/выключение камеры
  const toggleVideo = () => {
    if (localStream) {
      localStream.getVideoTracks().forEach((track) => (track.enabled = !track.enabled));
      setVideoEnabled((prev) => !prev);
    }
  };

  // Завершение звонка – закрытие соединения и остановка потоков
  const endCall = () => {
    if (peerConnectionRef.current) {
      peerConnectionRef.current.close();
      peerConnectionRef.current = null;
    }
    if (localStream) {
      localStream.getTracks().forEach((track) => track.stop());
      setLocalStream(null);
    }
    if (remoteStream) {
      remoteStream.getTracks().forEach((track) => track.stop());
      setRemoteStream(null);
    }
    setCallStatus('idle');
  };

  return (
    <div className="video-chat-container">
      <h2>Video Chat</h2>
      {callStatus === 'idle' ? (
        <button onClick={startCall}>Начать звонок</button>
      ) : (
        <button onClick={endCall}>Завершить звонок</button>
      )}
      <button onClick={toggleAudio}>
        {audioEnabled ? 'Выключить микрофон' : 'Включить микрофон'}
      </button>
      <button onClick={toggleVideo}>
        {videoEnabled ? 'Выключить камеру' : 'Включить камеру'}
      </button>
      <div className="video-container">
        <div className="local-video">
          <h3>Ваше видео</h3>
          <video ref={localVideoRef} autoPlay muted playsInline style={{ width: '100%' }} />
        </div>
        <div className="remote-video">
          <h3>Видео собеседника</h3>
          <video ref={remoteVideoRef} autoPlay playsInline style={{ width: '100%' }} />
        </div>
      </div>
    </div>
  );
};

export default VideoChat;
